// TH15 v1.00b Extra (stage 7) Boss9 -> BossCard9
// 「トリニタリアンラプソディ」 / spell id 117
// source: st07bs.ecl.txt:1271-1321 (Boss9 entry), 2508-2615 (BossCard9),
//         2657-2689 (tri1), 2691-2723 (tri2), 2725-2757 (tri3)
//
// Card frame 0 starts the phase timer.  The pattern task first runs one frame
// later, so its OPENING_BUFFER ends at card frame ~124 = source frame 0
// (Boss9 entry).  BossCard9's own timerReset is 160 frames later at ~284.
// TIME_LIMIT = 120 buffer + 160 wrapper wait + 5400 spell + 4 slack.

const TIME_LIMIT: int = 5684;
const OPENING_BUFFER: int = 120;

// TH15 type -> synthetic modern slot (type*16 + 352), see
// transcribe/th15/bullet-types.md.
const TH15_BALL2: int = 432;   // source type 5,  tri3 wave 1
const TH15_STAR_R: int = 608;  // source type 16, tri1/tri2 wave 1
const TH15_HEART: int = 816;   // source type 29, wave 2 (radius 10, color 0-7)

const SPELL_ID: int = 117;
const BOSS_HP: int = 3000;

// EX 0x2 ANIM a=1 keeps its birth retreat `position -= 4*velocity`:
// 4*2.5 = 10px for tri1/tri2, 4*1.5 = 6px for tri3.  Applied at fire().
//
// EX 0x80000000 WAIT n, then 0x200000 VELTIME a=40 target scalar speed.
// VELTIME ramps the scalar speed by a fixed per-frame delta and keeps the
// angle (r/s sentinel -999999); step_speed is the same linear scalar ramp.
xformdef RAMP40_TO_15 { wait(40); step_speed(1.5fx, 40 + 65536 * EASE_LINEAR); }
xformdef RAMP20_TO_15 { wait(20); step_speed(1.5fx, 40 + 65536 * EASE_LINEAR); }
xformdef RAMP20_TO_10 { wait(20); step_speed(1.0fx, 40 + 65536 * EASE_LINEAR); }
// EX WAIT n then 0x400 DELETE (a=0).  Target recycles at set_life(1).
xformdef ERASE_AFTER40 { wait(40); set_life(1); }
xformdef ERASE_AFTER20 { wait(20); set_life(1); }

// Source sub-enemies all set flag 259 (0x2 no body).  Target's spawned task
// first runs one frame after creation, so each launcher creates the child 48px
// toward the field centre (still on-screen, outside body range); the child
// teleports to its real source position on its first frame, with
// ENEMY_NO_BODY already set.

// tri1: 32x star (aimed ring, random base) then 64x heart, both 2.5,
// star decelerates to 1.5 after 40 frames, heart disappears after 40.
async sub tri1(tx: fx, ty: fx) {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(0, tx, ty, EASE_LINEAR);
    wait(109);                         // source wait(110) from the birth frame
    var base: angle = (rand(65536) - 32768) as angle;  // %RANDRAD, shared by both waves
    // etSprite(1,16,6), etAim(1,2), etCount(32,1), etAngle(%A,0), etSpeed(2.5),
    // ANIM(1), WAIT(40), VELTIME(40, r=1.5, s=-999999), etOn(1)
    sh_reset(0);
    sh_sprite(0, TH15_STAR_R, 6);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 32, 1);
    sh_speed(0, 2.5fx, 0fx);
    sh_angle(0, base, 0deg);
    sh_dist(0, -10fx);                 // ANIM a=1: 4*2.5 backward along each angle
    sh_xform(0, RAMP40_TO_15);
    sh_fire(0);
    // etNew(1), etSprite(1,29,3), etAim(1,2), etCount(64,1), etSpeed(2.5),
    // ANIM(1), BRIGHT(1), WAIT(40), DELETE(0), etOn(1)
    sh_reset(1);
    sh_sprite(1, TH15_HEART, 3);
    sh_ring(1, 1);
    sh_aim(1, 1);
    sh_count(1, 64, 1);
    sh_speed(1, 2.5fx, 0fx);
    sh_angle(1, base, 0deg);
    sh_dist(1, -10fx);
    sh_xform(1, ERASE_AFTER40);
    sh_fire(1);
}

// tri2: spawned at the player's position, 48x star + 64x heart at 2.5.
async sub tri2(tx: fx, ty: fx) {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(0, tx, ty, EASE_LINEAR);
    wait(109);
    var base: angle = (rand(65536) - 32768) as angle;
    // etSprite(1,16,10), etCount(48,1), etSpeed(2.5), ANIM(1), WAIT(20),
    // VELTIME(40, r=1.5), etOn(1)
    sh_reset(0);
    sh_sprite(0, TH15_STAR_R, 10);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 48, 1);
    sh_speed(0, 2.5fx, 0fx);
    sh_angle(0, base, 0deg);
    sh_dist(0, -10fx);
    sh_xform(0, RAMP20_TO_15);
    sh_fire(0);
    // etSprite(1,29,5), etCount(64,1), etSpeed(2.5), ANIM(1), BRIGHT(1),
    // WAIT(20), DELETE(0), etOn(1)
    sh_reset(1);
    sh_sprite(1, TH15_HEART, 5);
    sh_ring(1, 1);
    sh_aim(1, 1);
    sh_count(1, 64, 1);
    sh_speed(1, 2.5fx, 0fx);
    sh_angle(1, base, 0deg);
    sh_dist(1, -10fx);
    sh_xform(1, ERASE_AFTER20);
    sh_fire(1);
}

// tri3: 15x ball + 64x heart at 1.5.
async sub tri3(tx: fx, ty: fx) {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(0, tx, ty, EASE_LINEAR);
    wait(109);
    var base: angle = (rand(65536) - 32768) as angle;
    // etSprite(1,5,2), etCount(15,1), etSpeed(1.5), ANIM(1), WAIT(20),
    // VELTIME(40, r=1.0), etOn(1)
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 2);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 15, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_angle(0, base, 0deg);
    sh_dist(0, -6fx);                  // ANIM a=1: 4*1.5 backward along each angle
    sh_xform(0, RAMP20_TO_10);
    sh_fire(0);
    // etSprite(1,29,1), etCount(64,1), etSpeed(1.5), ANIM(1), BRIGHT(1),
    // WAIT(20), DELETE(0), etOn(1)
    sh_reset(1);
    sh_sprite(1, TH15_HEART, 1);
    sh_ring(1, 1);
    sh_aim(1, 1);
    sh_count(1, 64, 1);
    sh_speed(1, 1.5fx, 0fx);
    sh_angle(1, base, 0deg);
    sh_dist(1, -6fx);
    sh_xform(1, ERASE_AFTER20);
    sh_fire(1);
}

sub launch_tri1(tx: fx, ty: fx) {
    var dx: fx = 0fx - tx;
    var dy: fx = 224fx - ty;
    var dd: fx = dist(dx, dy);
    var sx: fx = tx + 48fx;
    var sy: fx = ty;
    if dd > 1fx {
        sx = tx + dx * 48fx / dd;
        sy = ty + dy * 48fx / dd;
    }
    _ = spawn_enemy(sx, sy, 10, 0, 1000, 0, tri1(tx, ty));
}

