// BossCard9 body.  Boss9's 160-frame hide/reposition is kept as the wrapper
// wait before this sub's own timer origin.
async sub card9() {
    wait(OPENING_BUFFER);              // source frame 0 = Boss9 entry
    // Boss9 1273-1302 boundary/no-op sequence: setInvuln(180) is covered by
    // the 65535 shell invuln; etCancel/etClear, killAllAsync, enmKillAll,
    // spellEnd, funcSet(0), laserCancel, bombShield, fog, setChapter,
    // unknown569, stars and the BossItemPhase3 drops have no standalone
    // effect here.  moveLimit(0,128,280,96) is reset before the only move
    // and the boss is stationary while it is active, so it cannot clip.
    // Boss9 1303-1316: stop motion, hide above the field, wait 160.
    // movePosTime(130, mode 1, 0, -64): mode 1 = EASE_QUAD_IN.
    move_to(130, $self_x, -64fx, EASE_QUAD_IN);
    wait(160);
    // flagSet(32) clears body/hit gates; anm sprites -1; movePos(0,224).
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(0, 0fx, 224fx, EASE_LINEAR);
    var t0: int = spell_timer();       // timerReset origin, in phase frames

    // ---- BossCard9 (timerReset is this instant) ----
    // First tri1 group at source label +90 (script time 94, i.e. 90 frames
    // after BossCard9's timerReset at nominal script time 4).
    wait(90);
    launch_tri1($self_x, $self_y);
    wait(120);
    launch_tri1($self_x + 128fx, $self_y - 128fx);
    launch_tri1($self_x - 128fx, $self_y - 128fx);
    wait(120);
    launch_tri1($self_x + 128fx, $self_y + 128fx);
    launch_tri1($self_x - 128fx, $self_y + 128fx);
    wait(120);
    launch_tri1($self_x, $self_y);
    wait(180);
    launch_tri1($self_x, $self_y - 160fx);
    launch_tri1($self_x + 160fx, $self_y + 144fx);
    launch_tri1($self_x - 160fx, $self_y + 144fx);
    wait(180);
    launch_tri1($self_x, $self_y + 160fx);
    launch_tri1($self_x + 160fx, $self_y - 144fx);
    launch_tri1($self_x - 160fx, $self_y - 144fx);
    wait(180);
    launch_tri1($self_x - 144fx, $self_y);
    launch_tri1($self_x + 144fx, $self_y + 180fx);
    launch_tri1($self_x + 144fx, $self_y - 180fx);
    wait(180);
    launch_tri1($self_x + 144fx, $self_y);
    launch_tri1($self_x - 144fx, $self_y + 180fx);
    launch_tri1($self_x - 144fx, $self_y - 180fx);
    wait(180);
    launch_tri1($self_x + 144fx, $self_y - 180fx);
    launch_tri1($self_x + 144fx, $self_y + 180fx);
    launch_tri1($self_x - 144fx, $self_y - 180fx);
    launch_tri1($self_x - 144fx, $self_y + 180fx);
    wait(280);

    // floatTime(0, %A, 1500, 0, 90, 20): interval A = 90 -> 20 over 1500f.
    // tri2 group spawns at the player position until $TIME >= 3300.
    // Read the phase timer instead of trusting the local sum: the pattern task
    // starts one frame after spell_begin, so this keeps the $TIME anchor exact.
    var a: fx = 90fx;
    var t: int = t0 - spell_timer();   // spell-relative frame at this point
    while t < 3300 {
        launch_tri2($player_x, $player_y);
        var b: int = a as int;         // _S(%A): float -> int
        wait(b);
        t = t0 - spell_timer();
        if t >= 2950 {
            a = 20fx;
        } else {
            a = 90fx - ((t - 1450) as fx * (70fx / 1500fx));
        }
    }
    // exit branch waits 280, then etClear and tri3 interval 120 -> 20 / 1620f.
    wait(280);
    t = t0 - spell_timer();
    var t3: int = t;
    var c: fx = 120fx;
    var d: angle = -90deg;             // %D = -1.570796f
    var g: int = 1000;
    // Stop spawning far enough before the 5400 timeout that every tri3 still
    // fires before the source attack is cleared (110-frame spawn delay).
    while g > 0 && t <= 5290 {
        launch_tri3($self_x + 192fx * cos(d),
                    $self_y + 192fx * sin(d));
        launch_tri3($self_x + 192fx * cos(d - 120deg),
                    $self_y + 192fx * sin(d - 120deg));
        launch_tri3($self_x + 192fx * cos(d + 120deg),
                    $self_y + 192fx * sin(d + 120deg));
        d = d + 15deg;                 // %D += 0.261799f
        var b2: int = c as int;
        wait(b2);
        t = t0 - spell_timer();
        g = g - 1;
        if t >= t3 + 1620 {
            c = 20fx;
        } else {
            c = 120fx - ((t - t3) as fx * (100fx / 1620fx));
        }
    }
    loop { wait(1); }
}

// Shell: the real boss carries the phase/spell.  The boss is invulnerable and
// has no body collision (source flagSet(32) before entering BossCard9).
async sub boss_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hurtbox(20fx);                 // st07bs 8-39: setHurtbox(40,40)
    set_hitbox(24fx);                  // st07bs 8-39: setHitbox(48,48)
    spell_begin(0, SPELL_ID, card9, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, BOSS_HP, 0, 0, 0, boss_main);
    loop { wait(1); }
}
